const request = require('supertest');
const app = require('../../index');

describe('A.1: Khởi tạo Đơn hàng (POST /)', () => {
    beforeEach(() => { jest.clearAllMocks(); });

    it('[Real Payload] [EP] ORD-CRE-01 - Khởi tạo hợp lệ với transcription', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "transcription",
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "service_type": "transcription",
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(201);
    });
    it('[Real Payload] [EP] ORD-CRE-04 - Lỗi rỗng service_type', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "",
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "service_type": "",
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [EP] ORD-CRE-05 - Lỗi sai định dạng service (Mảng)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": [
        "transcription"
    ],
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`); } catch(e) { payload = `{
    "service_type": [
        "transcription"
    ],
    "description": "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [EP] ORD-CRE-07 - Lỗi mô tả toàn khoảng trắng', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "recording",
    "description": "   "
}`); } catch(e) { payload = `{
    "service_type": "recording",
    "description": "   "
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [SEC] ORD-CRE-09 - Lỗi bảo mật: Không có token (401)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
  "service_type": "transcription",
  "description": "No token"
}`); } catch(e) { payload = `{
  "service_type": "transcription",
  "description": "No token"
}`; }
        const res = await request(app)
            .post('/').set('x-missing-token', 'true')
            .send(payload);
        
        expect(res.status).toBe(401);
    });
    it('[Real Payload] [SEC] ORD-CRE-10 - Lỗi bảo mật: Token sai (401/403)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
  "service_type": "transcription",
  "description": "Invalid token"
}`); } catch(e) { payload = `{
  "service_type": "transcription",
  "description": "Invalid token"
}`; }
        const res = await request(app)
            .post('/').set('Authorization', 'Bearer INVALID')
            .send(payload);
        
        expect(res.status).toBe(401);
    });
    it('[Real Payload] [BVA] ORD-CRE-02 - Khởi tạo hợp lệ tại biên min (1 ký tự)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "arrangement",
    "description": "A"
}`); } catch(e) { payload = `{
    "service_type": "arrangement",
    "description": "A"
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(201);
    });
    it('[Real Payload] [BVA] ORD-CRE-03 - Khởi tạo hợp lệ tại biên max (2000 ký tự)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "recording",
    "description": ""
}`); } catch(e) { payload = `{
    "service_type": "recording",
    "description": ""
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(201);
    });
    it('[Real Payload] [BVA] ORD-CRE-06 - Lỗi thiếu mô tả', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "recording"
}`); } catch(e) { payload = `{
    "service_type": "recording"
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
    it('[Real Payload] [BVA] ORD-CRE-08 - Lỗi mô tả vượt biên max (2001 ký tự)', async () => {
        global.mockPool.execute.mockResolvedValueOnce([[{ insertId: 9 }]]);
        let payload = null;
        try { payload = JSON.parse(`{
    "service_type": "transcription",
    "description": ""
}`); } catch(e) { payload = `{
    "service_type": "transcription",
    "description": ""
}`; }
        const res = await request(app)
            .post('/')
            .send(payload);
        
        expect(res.status).toBe(400);
    });
});